    "id": "spin",
    "type": "animation",
    "label": "Spin the pole",
    "loop": true,
    "teaches": "Physical rotation about the vertical axis produces stripes that appear to march straight downward — the perceived direction is not the real one."
  },
  {
    "id": "motionView",
    "type": "toggle",
    "label": "Motion overlay",
