// @FIGURE_CODE_BEGIN
// ── ELEMENT SPEC ─────────────────────────────────────────────────────────────
// barber pole        -> CylinderGeometry(1,1,5,96,1,openEnded,thetaStart=-90°) + ShaderMaterial broad helical stripes (red/white/blue), period W=1.8
// silhouette outline -> CylinderGeometry(1.03,1.03,5, openEnded) MeshBasicMaterial black BackSide
// top rim            -> TorusGeometry(1,0.026,8,120) black, y=+2.5
// bottom rim         -> TorusGeometry(1,0.026,8,120) black, y=-2.5
// open-top interior  -> CircleGeometry(0.995,96) white, y=+2.485
// rotation arrow     -> TubeGeometry(horizontal circle r=1.35, ~330°, y=3.45) black + ConeGeometry head at upper-right
// observed arrow     -> CylinderGeometry shaft + ConeGeometry head, black, at z=-3.2 (screen right)
// tracked dot        -> SphereGeometry(0.075) black riding surface r=1.02 at y=1.2, grey when behind
// dot path ring      -> TorusGeometry(1.02,0.012) grey, y=1.2  + grey leader line to caption at screen-left
// band marker        -> TorusGeometry(1.035,0.026) green, y animated downward + green leader line to caption at screen-right
// labels             -> addLabel serif ("Real motion", "Observed motion") + boxed captions for the two tracers

const R = 1.0, H = 5.0;
const W = 1.8;                   // stripe period measured perpendicular to the bands (broad helices)
const OMEGA = 0.6;               // rad/s
const D2R = Math.PI / 180;
const BLACK = 0x000000;

/* ── stripe shader on the curved surface ─────────────────────────────────── */
const stripeMat = new THREE.ShaderMaterial({
  uniforms: {
    uTheta: { value: 25 * D2R },
    uW:     { value: W },
    uR:     { value: R },
    uH:     { value: H },
    uShift: { value: 0.0 }
  },
  vertexShader: `
    varying vec2 vUv;
    varying vec3 vN;
    void main(){
      vUv = uv;
      vN = normalize(normalMatrix * normal);
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position,1.0);
    }`,
  fragmentShader: `
    precision highp float;
    varying vec2 vUv;
    varying vec3 vN;
    uniform float uTheta, uW, uR, uH, uShift;
    float band(float f, float a, float b, float w){
      return smoothstep(a-w, a+w, f) * (1.0 - smoothstep(b-w, b+w, f));
    }
    void main(){
      float s = vUv.x * 6.283185307 * uR - uShift;   // arc-length coordinate of the painted pattern
      float y = (vUv.y - 0.5) * uH;
      float ph = (y*cos(uTheta) - s*sin(uTheta)) / uW;   // stripes rise to the right
      float f = fract(ph);
      float g = clamp(abs(vN.z), 0.05, 1.0);             // soften where the surface turns away
      float w = clamp(0.009 / g, 0.003, 0.20);
      float red  = band(f, 0.12, 0.38, w);
      float blue = band(f, 0.62, 0.88, w);
      vec3 col = vec3(1.0);
      col = mix(col, vec3(0.93, 0.0, 0.0), red);
      col = mix(col, vec3(0.0, 0.0, 1.0), blue);
      gl_FragColor = vec4(col, 1.0);
    }`,
  side: THREE.DoubleSide
});

/* ── pole body ───────────────────────────────────────────────────────────── */
const pole = new THREE.Mesh(
  new THREE.CylinderGeometry(R, R, H, 96, 1, true, -Math.PI / 2, Math.PI * 2),
  stripeMat
);
scene.add(pole);

const outline = new THREE.Mesh(
  new THREE.CylinderGeometry(R * 1.03, R * 1.03, H * 1.002, 96, 1, true),
  new THREE.MeshBasicMaterial({ color: BLACK, side: THREE.BackSide })
);
scene.add(outline);

const topDisk = new THREE.Mesh(
  new THREE.CircleGeometry(R * 0.995, 96),
  new THREE.MeshBasicMaterial({ color: 0xffffff, side: THREE.DoubleSide })
);
topDisk.rotation.x = -Math.PI / 2;
topDisk.position.y = H / 2 - 0.015;
scene.add(topDisk);

function rimRing(y) {
  const t = new THREE.Mesh(
    new THREE.TorusGeometry(R, 0.026, 8, 140),
    new THREE.MeshBasicMaterial({ color: BLACK })
  );
  t.rotation.x = Math.PI / 2;
  t.position.y = y;
  scene.add(t);
  return t;
}
rimRing(H / 2);
rimRing(-H / 2);

/* ── rotation arrow above the pole ───────────────────────────────────────── */
const arrowY = 3.45, Rc = 1.35;
const phi0 = 1.25 * Math.PI;          // arrowhead at the upper-right of the ellipse
const sweep = Math.PI * 2 - 0.55;     // ~30° gap
const arcPts = [];
for (let i = 0; i <= 96; i++) {
  const p = phi0 + 0.06 + (sweep - 0.06) * (i / 96);
  arcPts.push(new THREE.Vector3(Rc * Math.cos(p), arrowY, Rc * Math.sin(p)));
}
const arcTube = new THREE.Mesh(
  new THREE.TubeGeometry(new THREE.CatmullRomCurve3(arcPts), 180, 0.040, 8, false),
  new THREE.MeshBasicMaterial({ color: BLACK })
);
scene.add(arcTube);

const tHead = new THREE.Vector3(Math.sin(phi0), 0, -Math.cos(phi0)).normalize(); // travel direction
const spinHead = new THREE.Mesh(
  new THREE.ConeGeometry(0.155, 0.40, 22),
  new THREE.MeshBasicMaterial({ color: BLACK })
);
spinHead.position.set(Rc * Math.cos(phi0), arrowY, Rc * Math.sin(phi0)).addScaledVector(tHead, 0.17);
spinHead.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), tHead);
scene.add(spinHead);

/* ── observed-motion (downward) arrow, screen right at z = -3.2 ──────────── */
const OBS_Z = -3.2, OBS_TOP = 0.35;
const obsGroup = new THREE.Group();
scene.add(obsGroup);
const obsShaft = new THREE.Mesh(
  new THREE.CylinderGeometry(0.04, 0.04, 1, 12),
  new THREE.MeshBasicMaterial({ color: BLACK })
);
const obsHead = new THREE.Mesh(
  new THREE.ConeGeometry(0.155, 0.36, 22),
  new THREE.MeshBasicMaterial({ color: BLACK })
);
obsHead.rotation.x = Math.PI;  // point down
obsGroup.add(obsShaft, obsHead);
obsGroup.position.set(0, 0, OBS_Z);

function setObsArrow(len) {
  const shaftLen = Math.max(0.05, len - 0.36);
  obsShaft.scale.y = shaftLen;
  obsShaft.position.set(0, OBS_TOP - shaftLen / 2, 0);
  obsHead.position.set(0, OBS_TOP - shaftLen - 0.18, 0);
}
setObsArrow(1.2);

/* ── overlays: tracked surface point & tracked stripe band ───────────────── */
const DOT_Y = 1.2;
const realGroup = new THREE.Group(); scene.add(realGroup);
const dot = new THREE.Mesh(
  new THREE.SphereGeometry(0.08, 20, 16),
  new THREE.MeshBasicMaterial({ color: BLACK })
);
const pathRing = new THREE.Mesh(
  new THREE.TorusGeometry(R * 1.02, 0.013, 6, 120),
  new THREE.MeshBasicMaterial({ color: 0x777777 })
);
pathRing.rotation.x = Math.PI / 2;
pathRing.position.y = DOT_Y;
// leader from the ring out to the caption at screen-left (+z)
const dotLeader = new THREE.Line(
  new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, DOT_Y, R * 1.05), new THREE.Vector3(0, DOT_Y, 1.72)
  ]),
  new THREE.LineBasicMaterial({ color: 0x777777 })
);
realGroup.add(dot, pathRing, dotLeader);

const obsGroup2 = new THREE.Group(); scene.add(obsGroup2);
const bandRing = new THREE.Mesh(
  new THREE.TorusGeometry(R * 1.035, 0.028, 8, 140),
  new THREE.MeshBasicMaterial({ color: 0x00a000 })
);
bandRing.rotation.x = Math.PI / 2;
const bandLeaderGeo = new THREE.BufferGeometry();
bandLeaderGeo.setAttribute('position', new THREE.BufferAttribute(new Float32Array(6), 3));
const bandLeader = new THREE.Line(bandLeaderGeo, new THREE.LineBasicMaterial({ color: 0x00a000 }));
obsGroup2.add(bandRing, bandLeader);

/* ── camera (perspective, slightly above eye level) ──────────────────────── */
setCameraView({
  projection: 'perspective',
  azimuthDeg: 0,
  elevationDeg: 19,
  rollDeg: 0,
  target: [0, 0.5, -0.75],
  heightFraction: 0.86
});
document.getElementById('btnReset').style.display = '';

/* ── labels ──────────────────────────────────────────────────────────────── */
const SERIF = 'font-family:Georgia,"Times New Roman",serif;';
addLabel(`<span style="${SERIF}">Real motion</span>`,
  new THREE.Vector3(0, 4.45, 1.85), { fontSize: '36px', color: '#000' });
addLabel(`<span style="${SERIF}text-align:center;display:block;line-height:1.08">Observed<br>motion</span>`,
  new THREE.Vector3(0, 1.35, OBS_Z), { fontSize: '36px', color: '#000' });

const dotLbl = addLabel('tracked surface point', new THREE.Vector3(0, DOT_Y, 1.78),
  { fontSize: '23px', color: '#000', offset: [0, -16], background: 'rgba(255,255,255,0.88)' });
dotLbl.div.style.border = '1px solid #bbb';

const bandLbl = addLabel('tracked stripe band', new THREE.Vector3(0, 0, -1.95),
  { fontSize: '23px', color: '#007000', offset: [0, -16], background: 'rgba(255,255,255,0.88)' });
bandLbl.div.style.border = '1px solid #9ec99e';

/* ── hover / click explanations ──────────────────────────────────────────── */
registerInteractive(pole, {
  title: 'Helical stripes on a rotating cylinder',
  tooltip: 'The stripes are continuous helices',
  body: 'The red and blue bands are broad helices painted on the curved surface. Every surface point travels on a horizontal circle, yet through the cylinder-shaped "aperture" the bands read as sliding straight down.'
});
registerInteractive(arcTube, {
  title: 'Real motion',
  tooltip: 'Real motion: spin about the vertical axis',
  body: 'The physical velocity of every point on the pole is horizontal, tangent to this circle: speed ω·R with ω ≈ 0.6 rad/s.'
});
registerInteractive(obsGroup, {
  title: 'Observed motion',
  tooltip: 'Observed motion: downward slide',
  body: 'The perceived velocity is vertical, with magnitude ω·R·tan θ, where θ is the stripe angle from horizontal. Only the component normal to a stripe is measurable locally, so the visual system fills in the rest along the pole — straight down.'
});
registerInteractive(dot, {
  title: 'Tracked surface point',
  tooltip: 'A real material point — it circles horizontally',
  body: 'This dot is glued to one point of the pole. It never moves down: it goes around and around, disappearing behind the far side.'
});
registerInteractive(bandRing, {
  title: 'Tracked stripe band',
  tooltip: 'A stripe band — it slides downward',
  body: 'This ring rides the centre of one red band. It descends at ω·R·tan θ although no matter descends at all.'
});

/* ── state & controls ────────────────────────────────────────────────────── */
let spinning = false;
let alpha = 0;                 // accumulated rotation (rad)
let thetaTarget = 25, thetaCur = 25;
let bandN = 0;

const $ = id => document.getElementById(id);
const btnSpin = $('btnSpin');
const angInput = $('angle');

function bandYFor(n, th) {
  const c = Math.cos(th), s = Math.sin(th);
  return ((n + 0.25) * W + R * (Math.PI - alpha) * s) / c;
}

btnSpin.addEventListener('click', () => setSpin(!spinning));
function setSpin(on) {
  spinning = on;
  btnSpin.textContent = on ? '❚❚ Pause rotation' : '▶ Spin the pole';
  btnSpin.classList.toggle('active', on);
}

const mvBtns = { real: $('mvReal'), observed: $('mvObs'), both: $('mvBoth') };
Object.keys(mvBtns).forEach(k => mvBtns[k].addEventListener('click', () => setView(k)));
function setView(v) {
  Object.keys(mvBtns).forEach(k => mvBtns[k].classList.toggle('active', k === v));
  const showReal = (v === 'real' || v === 'both');
  const showObs = (v === 'observed' || v === 'both');
  realGroup.visible = showReal;
  obsGroup2.visible = showObs;
  dotLbl.div.style.opacity = showReal ? '1' : '0';
  bandLbl.div.style.opacity = showObs ? '1' : '0';
}

angInput.addEventListener('input', () => { thetaTarget = parseFloat(angInput.value); });
function setAngle(a) { thetaTarget = a; angInput.value = a; }

/* ── guided demo ─────────────────────────────────────────────────────────── */
const STEPS = [
  { title: '1. The static pole',
    narration: 'A cylinder wrapped in broad red and blue helical stripes that rise to the right at about 25°. Nothing is moving yet.',
    state: { spin: false, view: 'real', angle: 25 } },
  { title: '2. Real motion: rotation',
    narration: 'Spin the pole about its vertical axis. The tracked surface dot travels horizontally around the cylinder — the true motion shown by the circular arrow on top.',
    state: { spin: true, view: 'real', angle: 25 } },
  { title: '3. Observed motion: downward slide',
    narration: 'Follow a stripe band instead. The same rotation now reads as bands sliding straight down, matching the "Observed motion" arrow.',
    state: { spin: true, view: 'observed', angle: 25 } },
  { title: '4. Both readings at once',
    narration: 'With both overlays on, the horizontal physical velocity and the vertical perceived velocity are visible simultaneously — the aperture problem in one picture.',
    state: { spin: true, view: 'both', angle: 25 } },
  { title: '5. Flatten the stripes',
    narration: 'Drop the stripe angle toward horizontal: the bands barely drift and the observed-motion arrow shrinks, even though the pole spins at exactly the same rate.',
    state: { spin: true, view: 'both', angle: 5 } },
  { title: '6. Steepen the stripes',
    narration: 'Raise the angle toward vertical: the same rotation now drives a fast downward slide and a long observed-motion arrow.',
    state: { spin: true, view: 'both', angle: 65 } }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  setSpin(st.state.spin);
  setView(st.state.view);
  setAngle(st.state.angle);
  $('stepTitle').textContent = st.title;
  $('stepNarr').textContent = st.narration;
}
$('prevStep').addEventListener('click', () => goToStep(stepIdx - 1));
$('nextStep').addEventListener('click', () => goToStep(stepIdx + 1));

/* ── per-frame update ────────────────────────────────────────────────────── */
let _last = performance.now();
function tick() {
  requestAnimationFrame(tick);
  const now = performance.now();
  const dt = Math.min(0.05, (now - _last) / 1000);
  _last = now;

  if (spinning) alpha += OMEGA * dt;

  thetaCur += (thetaTarget - thetaCur) * Math.min(1, 8 * dt);
  const th = thetaCur * D2R;
  stripeMat.uniforms.uTheta.value = th;
  stripeMat.uniforms.uShift.value = R * alpha;

  const vy = Math.min(OMEGA * R * Math.tan(th), 4.0);
  $('angVal').textContent = thetaCur.toFixed(0);
  $('spdVal').textContent = vy.toFixed(2);
  $('realVal').textContent = (OMEGA * R).toFixed(2);

  setObsArrow(Math.max(0.42, Math.min(2.3, 0.4 + 2.6 * vy)));

  // tracked surface point: front of the pole moves toward screen right
  dot.position.set(R * 1.02 * Math.cos(alpha), DOT_Y, -R * 1.02 * Math.sin(alpha));
  dot.material.color.set(Math.cos(alpha) < 0 ? 0x999999 : 0x000000);

  // tracked stripe band: exact centre of one red band at the front meridian
  let y = bandYFor(bandN, th), guard = 0;
  while (y < -2.35 && guard++ < 500) { bandN++; y = bandYFor(bandN, th); }
  while (y > 2.35 && guard++ < 500) { bandN--; y = bandYFor(bandN, th); }
  bandRing.position.y = y;
  const bp = bandLeaderGeo.attributes.position;
  bp.setXYZ(0, 0, y, -R * 1.06);
  bp.setXYZ(1, 0, y, -1.88);
  bp.needsUpdate = true;
  bandLeaderGeo.computeBoundingSphere();
  bandLbl.pos.set(0, y, -1.95);
}
goToStep(0);
tick();
